using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace ANetDesktop {
 public sealed class FakeClient:IClient {
  public bool LoginFailure,ReceiverMissing; public string ReceiverStatus="not_enabled";
  public readonly List<Dictionary<string,object>> Requests=new List<Dictionary<string,object>>();
  public Dictionary<string,object> Exchange(Dictionary<string,object> r){Requests.Add(new Dictionary<string,object>(r));string action=Data.Text(r,"action");if(action=="config.receiver"||action=="account.enable_receiver"){if(ReceiverMissing)return Data.Json.Deserialize<Dictionary<string,object>>(@"{""state"":""error"",""message"":""无法检查接收状态，请稍后刷新。""}");string operation=Data.Text(r,"operation");string state=operation=="prepare"?"prepared":action=="account.enable_receiver"?"testing":ReceiverStatus;return new Dictionary<string,object>{{"state","ready"},{"plan_id",state=="prepared"?"fixture-plan":""},{"receiver",new Dictionary<string,object>{{"state",state},{"ready",state=="ready"},{"detail",state=="prepared"?"条件检查完成，请确认后运行自检。":state=="testing"?"模型自检正在进行，请等待实际结果。":state=="ready"?"此设备可以接收已获账户授权的任务。":"尚未开启接收协作。"}}}};}if(action=="account.login"&&LoginFailure)return Data.Json.Deserialize<Dictionary<string,object>>(@"{""state"":""error"",""message"":""账户或密码不正确，请重新输入。"",""account"":{""state"":""needs_attention""},""connection"":{""state"":""needs_attention"",""detail"":""请检查账户和密码。""}}");if(action.StartsWith("account."))return Data.Json.Deserialize<Dictionary<string,object>>(@"{""state"":""ready"",""account"":{""url"":""https://124.222.173.36:8888"",""username"":""sample-user"",""state"":""signed_in""},""connection"":{""state"":""connected"",""hub_connected"":true,""portal_paired"":true,""detail"":""设备已连接。前往智能体，配置你常用的软件。""}}");return Data.Json.Deserialize<Dictionary<string,object>>(@"{""state"":""ready"",""workspace"":""D:\\ANet Workspace"",""agents"":[{""id"":""codex"",""name"":""Codex"",""configured"":true,""detail"":""ANet 配置已保存。请在软件中确认 MCP 连接。""},{""id"":""claude_code"",""name"":""Claude Code"",""state"":""not_configured"",""detail"":""连接后，在 Claude Code 中使用 ANet 工具。""},{""id"":""workbuddy"",""name"":""WorkBuddy"",""state"":""not_configured"",""detail"":""完成配置后，重新打开 WorkBuddy。""},{""id"":""deepseek_harness"",""name"":""DeepSeek Harness"",""state"":""not_configured"",""detail"":""请先在 DeepSeek Harness 中登录。""}],""services"":[{""id"":""node"",""name"":""ANet 连接服务"",""state"":""running"",""detail"":""这台电脑可连接 ANet 网络。""}]}");}
 }
 public static class ConfigUiCheck {
  static int count;
  static void Check(bool yes,string name){if(!yes)throw new Exception(name);count++;}
  static T Find<T>(Window w,string n)where T:class{return w.FindName(n)as T;}
  static Button ActionButton(DependencyObject root,string name){var b=root as Button;if(b!=null&&System.Windows.Automation.AutomationProperties.GetName(b)==name)return b;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=ActionButton(VisualTreeHelper.GetChild(root,i),name);if(found!=null)return found;}return null;}
  static void Shot(Window w,string file){w.UpdateLayout();var b=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(w);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var stream=File.Create(file))e.Save(stream);}
  [STAThread]public static int Main(string[] args){string output=args.Length>0?Path.GetFullPath(args[0]):Path.GetFullPath("ui-check");Directory.CreateDirectory(output);var app=new Application();Window w;using(var stream=typeof(Program).Assembly.GetManifestResourceStream("ANetDesktop.MainWindow.xaml"))w=(Window)XamlReader.Load(stream);w.ShowInTaskbar=false;w.Left=-16000;w.Top=-16000;var fake=new FakeClient();var runtime=new RuntimeConfig{Persistent=output};var view=new Workbench(w,runtime,fake,true);int result=1;
   w.ContentRendered+=async(s,e)=>{try{await Task.Delay(150);await view.RefreshAll();Check(fake.Requests.Count>=2,"startup reads config");foreach(var request in fake.Requests)Check(Data.Text(request,"action")=="account.status"||Data.Text(request,"action")=="config.status"||Data.Text(request,"action")=="config.receiver","startup must not create sources or tasks");Check(w.FindName("SubmitTask")==null&&w.FindName("CreateSource")==null,"no dispatch controls");Check(Find<TextBlock>(w,"ConnectionState").Text=="● 设备已连接","account status");
    foreach(string page in new[]{"Account","Agents","Workspace","Services"}){view.Navigate(page);Check(Find<FrameworkElement>(w,page+"Page").Visibility==Visibility.Visible,"page navigation "+page);Shot(w,Path.Combine(output,page+".png"));}
    w.Width=850;w.Height=660;view.Navigate("Agents");w.UpdateLayout();int receiverBefore=fake.Requests.Count;ActionButton(w,"Codex 设为接收协作执行器").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<FrameworkElement>(w,"ReceiverPanel").Visibility==Visibility.Visible,"receiver prepared panel visible");Check(!fake.Requests.Exists(r=>Data.Text(r,"action")=="account.enable_receiver"),"prepare never enables or calls model");Find<PasswordBox>(w,"ReceiverPassword").Password="discard-on-new-selection";ActionButton(w,"Codex 设为接收协作执行器").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<PasswordBox>(w,"ReceiverPassword").Password=="","new receiver choice clears password");w.Width=850;w.Height=660;Shot(w,Path.Combine(output,"Receiver-prepared-narrow.png"));w.Width=1080;w.Height=780;Find<PasswordBox>(w,"ReceiverPassword").Password="receiver-fixture-secret";Find<Button>(w,"ReceiverEnable").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<PasswordBox>(w,"ReceiverPassword").Password=="","receiver enable clears password");Check(fake.Requests.Exists(r=>Data.Text(r,"action")=="account.enable_receiver"&&Data.Flag(r,"confirm")&&Data.Text(r,"plan_id")=="fixture-plan"&&Data.Text(r,"password")=="receiver-fixture-secret"),"receiver explicit confirmed request");Check(Find<TextBlock>(w,"ReceiverState").Foreground.ToString()!="#FF38E8C6","receiver testing not green");Check(Find<FrameworkElement>(w,"ReceiverPanel").Visibility==Visibility.Collapsed,"testing cannot duplicate enable");Check(Find<TextBlock>(w,"NoticeText").Text.IndexOf("receiver-fixture-secret")<0,"receiver password absent from notice");Shot(w,Path.Combine(output,"Receiver-testing.png"));fake.ReceiverStatus="ready";Find<Button>(w,"ReceiverRefresh").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<TextBlock>(w,"ReceiverState").Foreground.ToString()=="#FF38E8C6","verified receiver ready green");fake.ReceiverMissing=true;Find<Button>(w,"ReceiverRefresh").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<TextBlock>(w,"ReceiverState").Foreground.ToString()!="#FF38E8C6","receiver failed refresh clears old green");fake.ReceiverMissing=false;
    view.Navigate("Account");Find<TextBox>(w,"Username").Text="test-user";Find<PasswordBox>(w,"Password").Password="fixture-secret";Find<Button>(w,"Login").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<PasswordBox>(w,"Password").Password=="","password cleared");Check(fake.Requests.Exists(r=>Data.Text(r,"action")=="account.login"&&Data.Text(r,"password")=="fixture-secret"),"login request");
    fake.LoginFailure=true;Find<TextBox>(w,"Username").Text="test-user";Find<PasswordBox>(w,"Password").Password="must-not-appear";Find<Button>(w,"Login").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(Find<PasswordBox>(w,"Password").Password=="","password cleared after failed login");Check(Find<TextBlock>(w,"NoticeText").Text.IndexOf("must-not-appear")<0,"error notice never contains password");Check(Find<TextBlock>(w,"ConnectionState").Text=="○ 设备尚未连接","failed login not green");Shot(w,Path.Combine(output,"Account-error.png"));int before=fake.Requests.Count;Find<TextBox>(w,"PortalUrl").Text="http://example.invalid";Find<PasswordBox>(w,"Password").Password="fixture-secret";Find<Button>(w,"Login").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(50);Check(fake.Requests.Count==before,"HTTP login refused before sending password");Find<PasswordBox>(w,"Password").Clear();Find<TextBox>(w,"PortalUrl").Text="https://124.222.173.36:8888";
    w.Width=850;w.Height=660;view.Navigate("Account");Shot(w,Path.Combine(output,"Account-narrow.png"));Check(Find<TextBox>(w,"PortalUrl").ActualWidth>300,"narrow account layout");result=0;File.WriteAllText(Path.Combine(output,"checks.json"),Data.Json.Serialize(new{passed=count,failed=0,task_calls=0}));Console.WriteLine("Passed "+count+" WPF checks");
   }catch(Exception error){Console.Error.WriteLine(error);result=1;}finally{app.Shutdown();}};app.Run(w);return result;
  }
 }
}
